svg.script:
(function(){
var svg=document.documentElement;
var NS='http://www.w3.org/2000/svg';
Array.prototype.forEach.call(document.querySelectorAll('.term'),function(el){
  var b=el.getBBox();var r=document.createElementNS(NS,'rect');
  r.setAttribute('x',(b.x-4).toFixed(1));r.setAttribute('y',(b.y+2).toFixed(1));
  r.setAttribute('width',(b.width+8).toFixed(1));r.setAttribute('height',(b.height).toFixed(1));
  r.setAttribute('rx','4');r.setAttribute('fill','#4d4436');r.setAttribute('pointer-events','none');
  r.setAttribute('stroke','#ffffff');r.setAttribute('stroke-width','0.6');r.setAttribute('stroke-opacity','0.35');
  var tp=el.parentNode;tp.parentNode.insertBefore(r,tp);
});
var tt=document.createElementNS(NS,'g');
tt.setAttribute('visibility','hidden');tt.setAttribute('pointer-events','none');tt.setAttribute('opacity','0.8');
var bg=document.createElementNS(NS,'rect');
bg.setAttribute('fill','#1d1e19');bg.setAttribute('fill-opacity','0.96');
bg.setAttribute('stroke','#66d9ef');bg.setAttribute('rx','4');
var tx=document.createElementNS(NS,'text');
tx.setAttribute('font-size','11');tx.setAttribute('font-family',"'Segoe UI', sans-serif");
tt.appendChild(bg);tt.appendChild(tx);svg.appendChild(tt);
function segs(parent,text,def){
  var parts=text.split('`');
  for(var j=0;j<parts.length;j++){
    var s=document.createElementNS(NS,'tspan');
    if(j%2===0){if(!parts[j])continue;s.setAttribute('fill',def);s.textContent=parts[j];}
    else{var t2=parts[j].slice(6);if(!t2)continue;s.setAttribute('fill','#'+parts[j].slice(0,6));s.textContent=t2;}
    parent.appendChild(s);
  }
}
function show(el,evt){
  while(tx.firstChild)tx.removeChild(tx.firstChild);
  var lines=(el.getAttribute('data-tip')||'').split('\n');
  var hl=el.getAttribute('data-hl')||'#66d9ef';
  var nc=el.getAttribute('data-nc')||hl;
  bg.setAttribute('stroke',hl);
  var name=null;
  for(var i=0;i<lines.length;i++){
    var t=document.createElementNS(NS,'tspan');
    t.setAttribute('x','8');t.setAttribute('dy',i===0?'17':'14');
    if(i===0){
      t.setAttribute('font-weight','700');t.setAttribute('font-size','13');
      t.setAttribute('fill',nc);t.textContent=lines[i];name=t;
    }else{
      var bt=lines[i].indexOf('`');var p=lines[i].indexOf(': ');
      if(p>0&&(bt<0||bt>p)){
        var b=document.createElementNS(NS,'tspan');
        b.setAttribute('font-weight','700');b.setAttribute('fill','#f8f8f2');
        b.textContent=lines[i].slice(0,p+1);t.appendChild(b);
        segs(t,' '+lines[i].slice(p+2),'#cfcfc2');
      }else if(lines[i].indexOf('->|')===0||lines[i].indexOf('|->')===0){
        var cut=(bt<0?lines[i].length:bt);
        var mk=document.createElementNS(NS,'tspan');
        mk.setAttribute('font-weight','700');mk.setAttribute('fill','#cfcfc2');
        mk.textContent=lines[i].slice(0,cut);t.appendChild(mk);
        segs(t,lines[i].slice(cut),'#cfcfc2');
      }else{segs(t,lines[i],'#cfcfc2');}
    }
    tx.appendChild(t);
  }
  tt.setAttribute('visibility','visible');
  var prio=el.getAttribute('data-prio');
  if(prio&&name){
    var b0=tx.getBBox();var pr=document.createElementNS(NS,'tspan');
    pr.setAttribute('y','17');pr.setAttribute('font-weight','700');pr.setAttribute('font-size','12');
    pr.setAttribute('text-anchor','end');pr.setAttribute('fill',el.getAttribute('data-pc')||nc);
    pr.textContent=prio;tx.appendChild(pr);
    var rt=Math.max(b0.x+b0.width, 8+name.getComputedTextLength()+18+pr.getComputedTextLength());
    pr.setAttribute('x',rt);
  }
  move(evt);
}
function move(evt){
  var pt=svg.createSVGPoint();pt.x=evt.clientX;pt.y=evt.clientY;
  var m=svg.getScreenCTM();if(m)pt=pt.matrixTransform(m.inverse());
  var b=tx.getBBox();var w=b.width+16,h=b.height+12;
  bg.setAttribute('width',w);bg.setAttribute('height',h);
  var vb=svg.viewBox.baseVal;
  var x=pt.x+14,y=pt.y+14;
  if(x+w>vb.width-4)x=pt.x-w-10;if(x<4)x=4;
  if(y+h>vb.height-4)y=pt.y-h-10;if(y<4)y=4;
  tt.setAttribute('transform','translate('+x+','+y+')');
}
var edges=document.querySelectorAll('.edge');
var bars=document.querySelectorAll('.hv[data-node]');
var anchor=bars.length?bars[0]:null;
var fg=document.createElementNS(NS,'g');svg.insertBefore(fg,tt);
function sink(e){if(anchor)anchor.parentNode.insertBefore(e,anchor);}
if(anchor)Array.prototype.forEach.call(edges,function(e){sink(e);});
function hiEdges(id){Array.prototype.forEach.call(edges,function(e){if((e.getAttribute('data-a')===id||e.getAttribute('data-b')===id)&&parseFloat(e.getAttribute('data-op'))>0){e.setAttribute('opacity','1');e.setAttribute('pointer-events','none');fg.appendChild(e);}});}
function loEdges(){while(fg.firstChild){var c=fg.firstChild;c.setAttribute('opacity',c.getAttribute('data-op'));c.setAttribute('pointer-events','auto');sink(c);}}
Array.prototype.forEach.call(document.querySelectorAll('.hv'),function(el){
  el.addEventListener('mouseenter',function(e){loEdges();show(el,e);var n=el.getAttribute('data-node');
    if(n!==null)hiEdges(n);else if(el.getAttribute('data-a')!==null){el.setAttribute('opacity','1');fg.appendChild(el);}});
  el.addEventListener('mousemove',move);
  el.addEventListener('mouseleave',function(){tt.setAttribute('visibility','hidden');loEdges();});
});
var critView=false,edgesOn=true,kindMode=0,coneMode=false,coneNode=null,deadView=false,metricMode=0;
var deadbands=document.querySelectorAll('.deadband');
Array.prototype.forEach.call(edges,function(e){e._op0=parseFloat(e.getAttribute('data-op'));});
Array.prototype.forEach.call(deadbands,function(r){r._op0=parseFloat(r.getAttribute('opacity'))||0.1;});
Array.prototype.forEach.call(bars,function(g){var r=g.querySelector('rect');if(r)g._st0=r.getAttribute('stroke');});
var inAdj={},outAdj={};
Array.prototype.forEach.call(edges,function(e){var a=e.getAttribute('data-a'),b=e.getAttribute('data-b');(outAdj[a]=outAdj[a]||[]).push(b);(inAdj[b]=inAdj[b]||[]).push(a);});
function walk(start,adj){var seen={},st=[start];while(st.length){var n=st.pop();var nb=adj[n]||[];for(var i=0;i<nb.length;i++){if(!seen[nb[i]]){seen[nb[i]]=1;st.push(nb[i]);}}}return seen;}
function cone(id){var s={};s[id]=1;var up=walk(id,inAdj),dn=walk(id,outAdj);for(var k in up)s[k]=1;for(var k2 in dn)s[k2]=1;return s;}
function ramp(t){t=Math.max(0,Math.min(1,t));var a,b,f;if(t<0.5){a=[0xa6,0xe2,0x2e];b=[0xe6,0xdb,0x74];f=t*2;}else{a=[0xe6,0xdb,0x74];b=[0xff,0x5f,0x45];f=(t-0.5)*2;}var r=Math.round(a[0]+(b[0]-a[0])*f),g=Math.round(a[1]+(b[1]-a[1])*f),c=Math.round(a[2]+(b[2]-a[2])*f);return '#'+((1<<24)+(r<<16)+(g<<8)+c).toString(16).slice(1);}
function paintMetric(){
  if(metricMode===0){Array.prototype.forEach.call(bars,function(g){var r=g.querySelector('rect');if(r&&g._st0)r.setAttribute('stroke',g._st0);});return;}
  var attr=metricMode===1?'data-dispatch':'data-slack';var mx=0;
  Array.prototype.forEach.call(bars,function(g){mx=Math.max(mx,parseFloat(g.getAttribute(attr))||0);});
  if(mx<=0)mx=1;
  Array.prototype.forEach.call(bars,function(g){var v=(parseFloat(g.getAttribute(attr))||0)/mx;var t=metricMode===2?1-v:v;var r=g.querySelector('rect');if(r)r.setAttribute('stroke',ramp(t));});
}
function restyle(){
  var cs=(coneMode&&coneNode!=null)?cone(coneNode):null;
  Array.prototype.forEach.call(bars,function(g){var op=1;
    if(critView&&(parseFloat(g.getAttribute('data-crit'))||0)<0.15)op=Math.min(op,0.15);
    if(cs&&!cs[g.getAttribute('data-node')])op=Math.min(op,0.12);
    if(deadView)op=Math.min(op,0.30);
    g.setAttribute('opacity',op);});
  Array.prototype.forEach.call(edges,function(e){var op=e._op0;
    var a=e.getAttribute('data-a'),b=e.getAttribute('data-b');
    if(!edgesOn)op=0;
    if(kindMode===1&&e.getAttribute('data-kind')!=='explicit')op=0;
    if(kindMode===2&&e.getAttribute('data-kind')!=='derived')op=0;
    if(critView&&(parseFloat(e.getAttribute('data-crit'))||0)<0.15)op=Math.min(op,0.03);
    if(cs&&!(cs[a]&&cs[b]))op=Math.min(op,0.03);
    if(deadView)op=Math.min(op,0.04);
    e.setAttribute('data-op',op);if(e.parentNode!==fg)e.setAttribute('opacity',op);});
  Array.prototype.forEach.call(deadbands,function(r){r.setAttribute('opacity',deadView?Math.min(1,r._op0*3+0.3):r._op0);});
  paintMetric();
}
function setActive(b,on){var r=b.querySelector('rect');if(!r)return;r.setAttribute('fill',on?'#75715e':'#3e3d32');r.setAttribute('stroke',on?'#a6e22e':'#75715e');}
function setLabel(b,t){var x=b.querySelector('text');if(x)x.textContent=t;}
Array.prototype.forEach.call(document.querySelectorAll('.btn'),function(b){
  b.addEventListener('click',function(ev){ev.stopPropagation();var v=b.getAttribute('data-view');
    if(v==='crit'){critView=!critView;setActive(b,critView);}
    else if(v==='edges'){edgesOn=!edgesOn;setActive(b,!edgesOn);setLabel(b,'Edges: '+(edgesOn?'on':'off'));}
    else if(v==='kind'){kindMode=(kindMode+1)%3;setActive(b,kindMode!==0);setLabel(b,'Edge type: '+['all','explicit','derived'][kindMode]);}
    else if(v==='cone'){coneMode=!coneMode;if(!coneMode)coneNode=null;setActive(b,coneMode);setLabel(b,'Cone: '+(coneMode?'pick':'off'));}
    else if(v==='dead'){deadView=!deadView;setActive(b,deadView);}
    else if(v==='metric'){metricMode=(metricMode+1)%3;setActive(b,metricMode!==0);setLabel(b,'Colour: '+['crit','dispatch','slack'][metricMode]);}
    restyle();});
});
var coneBtn=document.querySelector('.btn[data-view="cone"]');
Array.prototype.forEach.call(bars,function(g){g.addEventListener('click',function(ev){if(coneMode){coneNode=g.getAttribute('data-node');ev.stopPropagation();if(coneBtn)setLabel(coneBtn,'Cone: set');restyle();}});});
svg.addEventListener('click',function(){if(coneMode&&coneNode!=null){coneNode=null;if(coneBtn)setLabel(coneBtn,'Cone: pick');restyle();}});
})();
